-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.bury_cards(cards jsonb, until timestamp with time zone, note boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  action uuid := gen_random_uuid();
  card jsonb;
  n integer := 0;
begin
  if not public.is_allowed_user() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  perform public.lock_user_study();
  for card in select * from jsonb_array_elements(cards) loop
    if public.change_card(action, case when note then 'bury_note' else 'bury_card' end, card, now(),
                          jsonb_build_object('buried_until', until)) then
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$function$;

grant execute on function public.bury_cards(cards jsonb, until timestamp with time zone, note boolean) to authenticated;
grant execute on function public.bury_cards(cards jsonb, until timestamp with time zone, note boolean) to service_role;
